const items = $input.all();

if (!items.length) {
  throw new Error("No input items received.");
}

// --------------------------------------
// 1️⃣ Merge repo + config safely
// --------------------------------------

let merged = {};
for (const item of items) {
  merged = { ...merged, ...item.json };
}

const tree = merged.tree || [];

if (!Array.isArray(tree)) {
  throw new Error("Repo tree not found.");
}

// --------------------------------------
// 2️⃣ Normalize Config Arrays
// --------------------------------------

function normalize(arr) {
  return Array.isArray(arr)
    ? arr.map(v => String(v).toLowerCase())
    : [];
}

const tierAConfigFiles = normalize(merged.tierAConfigFiles);
const ignoreFolders = normalize(merged.ignoreFolders);
const ignorePatterns = normalize(merged.ignorePatterns);
const codeExtensions = normalize(merged.codeExtensions);

// --------------------------------------
// 3️⃣ Generic Helpers
// --------------------------------------

const MAX_FILE_SIZE = 150000;
const MAX_FILES_PER_DIRECTORY = 25;
const directoryCounter = {};

function getExtension(fileName) {
  const parts = fileName.split(".");
  return parts.length > 1
    ? parts.slice(1).join(".").toLowerCase()
    : "";
}

function pathSegments(path) {
  return path.toLowerCase().split("/");
}

function matchesWildcard(value, pattern) {
  const regex = new RegExp(
    "^" +
      pattern
        .replace(/\./g, "\\.")
        .replace(/\*/g, ".*") +
      "$",
    "i"
  );
  return regex.test(value);
}

function isIgnored(path, fileName) {
  const segments = pathSegments(path);

  // Ignore folders (structural match)
  if (segments.some(seg => ignoreFolders.includes(seg))) {
    return true;
  }

  // Ignore wildcard patterns
  if (ignorePatterns.some(p => matchesWildcard(fileName, p))) {
    return true;
  }

  return false;
}

// --------------------------------------
// 4️⃣ Tier Detection (Generic)
// --------------------------------------

function detectTier(file) {
  const path = file.path.toLowerCase();
  const fileName = path.split("/").pop();
  const ext = getExtension(fileName);
  const depth = pathSegments(path).length;

  // Tier A → Explicit config match
  if (tierAConfigFiles.includes(fileName)) {
    return "A";
  }

  // Tier A → Root level config-like files
  if (depth === 1 && ext === "json") {
    return "A";
  }

  // Tier C → Very deep + atomic-like files
  if (depth > 5) {
    return "C";
  }

  // Tier B → Default business logic
  return "B";
}

// --------------------------------------
// 5️⃣ Generic Filtering Loop
// --------------------------------------

const filtered = [];

for (const file of tree) {

  if (!file || file.type !== "blob") continue;

  if (file.size && file.size > MAX_FILE_SIZE) continue;

  const path = file.path.toLowerCase();
  const fileName = path.split("/").pop();
  const ext = getExtension(fileName);

  if (isIgnored(path, fileName)) continue;

  const isConfig = tierAConfigFiles.includes(fileName);
  const isCode = codeExtensions.includes(ext);

  if (!isConfig && !isCode) continue;

  const directoryKey = pathSegments(path).slice(0, 2).join("/") || "root";

  if (!directoryCounter[directoryKey]) {
    directoryCounter[directoryKey] = 0;
  }

  if (directoryCounter[directoryKey] >= MAX_FILES_PER_DIRECTORY) {
    continue;
  }

  directoryCounter[directoryKey]++;

  file.tier = detectTier(file);

  filtered.push(file);
}

// --------------------------------------
// 6️⃣ Output
// --------------------------------------

return filtered.map(f => ({
  json: {
    owner: merged.owner,
    repo: merged.repo,
    branch: merged.branch,
    repoSha: merged.sha,
    tier: f.tier,
    ...f
  }
}));

const items = $input.all();

function getLogicalGroup(path) {
  if (!path) return "unknown";

  const parts = path.split("/");

  // Root-level files (no folder)
  if (parts.length === 1) {
    return "root";
  }

  // Use first directory as logical group
  return parts[0];
}

const grouped = {};

for (const item of items) {
  const path = item.json.path;
  const summary = item.json.summary;

  if (!path || !summary) continue;

  const group = getLogicalGroup(path);

  if (!grouped[group]) {
    grouped[group] = [];
  }

  // Optional: cap files per folder (protect tokens)
  if (grouped[group].length < 25) {
    grouped[group].push({
      path,
      summary
    });
  }
}

return Object.keys(grouped).map(folder => ({
  json: {
    folder,
    files: grouped[folder]
  }
}));

const items = $input.all();
const maxChars = 4000;

return items.map(item => {

  const raw = item.json.data || "";

  const truncated = raw.length > maxChars
    ? raw.slice(0, maxChars) + "\n\n...TRUNCATED..."
    : raw;

  return {
    json: {
      owner: item.json.owner,
      repo: item.json.repo,
      branch: item.json.branch,
      path: item.json.path,
      mode: item.json.mode,
      type: item.json.type,
      sha: item.json.sha,
      size: item.json.size,
      url: item.json.url,
      tier: item.json.tier,   // keep tier if you added it earlier
      content: truncated
    }
  };
});

const items = $input.all();

return items.map(item => {
  const rawText = item.json.output?.[0]?.content?.[0]?.text;

  if (!rawText) {
    return { json: { error: "No summary returned" } };
  }

  let parsed;

  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    return { json: { error: "Invalid JSON from LLM", raw: rawText } };
  }

  return {
    json: {
      path: parsed.path,
      summary: parsed.summary
    }
  };
});

const rawText = $json.output?.[0]?.content?.[0]?.text;

if (!rawText) {
  return [{ json: { error: "No folder analysis returned" } }];
}

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (e) {
  return [{ json: { error: "Invalid JSON from Folder Analyzer", raw: rawText } }];
}

return [{ json: parsed }];

const folders = $input.all().map(i => i.json);

return [{
  json: {
    folders
  }
}];

const rawText = $json.output?.[0]?.content?.[0]?.text;

if (!rawText) {
  return [{ json: { error: "No system architecture returned" } }];
}

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (e) {
  return [{ json: { error: "Invalid JSON from System Synthesizer", raw: rawText } }];
}

return [{ json: parsed }];

const {
  Document,
  Packer,
  Paragraph,
  TextRun,
  HeadingLevel,
  AlignmentType,
  TableOfContents,
  Header,
  Footer,
  PageNumber,
  BorderStyle
} = require("docx");

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error("No input data received.");
}

const hld = items[0].json;
if (!hld || hld.error) {
  throw new Error("HLD generation failed or returned insufficient intelligence.");
}

const timestamp = new Date();
const formattedTime = timestamp.toLocaleString();
const repoName = (hld.systemType || "System").replace(/\s+/g, "_");
const fileName = `HLD_${repoName}_${timestamp.toISOString().replace(/[:.]/g, "-")}.docx`;

function safe(value, fallback = "Not available") {
  return value ? value : fallback;
}

function bodyText(text) {
  return safe(text)
    .split("\n")
    .map(line =>
      new Paragraph({
        spacing: { after: 200 },
        children: [
          new TextRun({
            text: line,
            font: "Calibri",
            size: 22
          })
        ],
      })
    );
}

function sectionDivider() {
  return new Paragraph({
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 6, color: "DDDDDD" },
    },
    spacing: { after: 300 },
  });
}

const children = [];

//
// COVER PAGE
//
children.push(
  new Paragraph({
    text: "HIGH LEVEL DESIGN",
    heading: HeadingLevel.TITLE,
    alignment: AlignmentType.CENTER,
    spacing: { after: 300 },
  })
);

children.push(
  new Paragraph({
    children: [
      new TextRun({
        text: repoName,
        bold: true,
        font: "Calibri",
        size: 28,
      }),
    ],
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 },
  })
);

children.push(
  new Paragraph({
    children: [
      new TextRun({
        text: `Generated On: ${formattedTime}`,
        italics: true,
        font: "Calibri",
        size: 22,
      }),
    ],
    alignment: AlignmentType.CENTER,
  })
);

children.push(new Paragraph({ pageBreakBefore: true }));

//
// TABLE OF CONTENTS
//
children.push(
  new Paragraph({
    text: "Table of Contents",
    heading: HeadingLevel.HEADING_1,
    spacing: { after: 200 },
  })
);

children.push(
  new TableOfContents("Table of Contents", {
    hyperlink: true,
    headingStyleRange: "1-3",
  })
);

children.push(new Paragraph({ pageBreakBefore: true }));

//
// SECTION TEMPLATE FUNCTION
//
function addSection(title, contentBuilder) {
  children.push(
    new Paragraph({
      text: title,
      heading: HeadingLevel.HEADING_1,
      spacing: { before: 300, after: 200 },
    })
  );

  contentBuilder();

  children.push(sectionDivider());
}

//
// 1. OVERVIEW
//
addSection("1. Overview", () => {
  children.push(...bodyText(hld.overview));
});

//
// 2. MAJOR COMPONENTS
//
addSection("2. Major Components", () => {
  if (Array.isArray(hld.majorComponents) && hld.majorComponents.length > 0) {
    hld.majorComponents.forEach(comp => {
      children.push(
        new Paragraph({
          text: safe(comp.name, "Unnamed Component"),
          heading: HeadingLevel.HEADING_2,
          spacing: { before: 200, after: 100 },
        })
      );
      children.push(...bodyText(comp.description));
    });
  } else {
    children.push(...bodyText("No major components identified."));
  }
});

//
// 3. EXTERNAL INTEGRATIONS
//
addSection("3. External Integrations", () => {
  if (Array.isArray(hld.externalIntegrations) && hld.externalIntegrations.length > 0) {
    hld.externalIntegrations.forEach(ext => {
      children.push(
        new Paragraph({
          text: safe(ext.name, "Unnamed Integration"),
          heading: HeadingLevel.HEADING_2,
          spacing: { before: 200, after: 100 },
        })
      );
      children.push(...bodyText(ext.purpose));
    });
  } else {
    children.push(...bodyText("No external integrations identified."));
  }
});

//
// 4. DATA FLOW
//
addSection("4. Data Flow", () => {
  children.push(...bodyText(hld.dataFlow));
});

//
// 5. ARCHITECTURAL PATTERNS
//
addSection("5. Architectural Patterns", () => {
  if (Array.isArray(hld.architecturePatterns) && hld.architecturePatterns.length > 0) {
    hld.architecturePatterns.forEach(pattern => {
      children.push(
        new Paragraph({
          bullet: { level: 0 },
          spacing: { after: 100 },
          children: [
            new TextRun({
              text: pattern,
              font: "Calibri",
              size: 22,
            }),
          ],
        })
      );
    });
  } else {
    children.push(...bodyText("No architectural patterns identified."));
  }
});

//
// 6. DEPLOYMENT
//
addSection("6. Deployment Considerations", () => {
  children.push(...bodyText(hld.deploymentConsiderations));
});

//
// 7. MERMAID SOURCE
//
addSection("7. Architecture Diagram (Mermaid Source)", () => {
  children.push(
    new Paragraph({
      spacing: { after: 200 },
      border: {
        top: { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" },
        bottom: { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" },
        left: { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" },
        right: { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" },
      },
      children: [
        new TextRun({
          text: safe(hld.mermaidDiagram),
          font: "Courier New",
          size: 20,
        }),
      ],
    })
  );
});

//
// HEADER & FOOTER
//
const header = new Header({
  children: [
    new Paragraph({
      alignment: AlignmentType.RIGHT,
      children: [
        new TextRun({
          text: `HLD - ${repoName}`,
          font: "Calibri",
          size: 20,
        }),
      ],
    }),
  ],
});

const footer = new Footer({
  children: [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({
          text: "Page ",
          font: "Calibri",
          size: 20,
        }),
        PageNumber.CURRENT,
      ],
    }),
  ],
});

//
// DOCUMENT CONFIG
//
const doc = new Document({
  sections: [
    {
      properties: {
        page: {
          margin: {
            top: 1440,
            right: 1440,
            bottom: 1440,
            left: 1440,
          },
        },
      },
      headers: { default: header },
      footers: { default: footer },
      children,
    },
  ],
});

const buffer = await Packer.toBuffer(doc);

return [
  {
    json: { fileName },
    binary: {
      data: {
        data: buffer.toString("base64"),
        mimeType:
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        fileName,
      },
    },
  },
];

const text = items[0].json.output[0].content[0].text;

if (!text) {
  throw new Error("No JSON text found in model output.");
}

return [
  {
    json: {
      rawHldJson: text.trim()
    }
  }
];

const raw = items[0].json.rawHldJson;

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (err) {
  throw new Error("HLD JSON parsing failed. Output likely truncated.");
}

return [
  {
    json: parsed
  }
];

const tree = $json.tree || [];

// ===============================
// DATA STRUCTURES
// ===============================
const extensions = new Set();
const folders = new Set();
const fileNames = new Set();

const extensionFrequency = {};
const folderFileCount = {};
const unmatchedPaths = [];

let totalTreeItems = tree.length;
let totalBlobs = 0;
let skippedNonBlobs = 0;
let filesWithoutExtension = 0;
let rootLevelFiles = 0;

let minFileSize = Number.MAX_SAFE_INTEGER;
let maxFileSize = 0;
let totalFileSize = 0;

let maxDepth = 0;

// ===============================
// MAIN TRAVERSAL LOOP
// ===============================
for (const file of tree) {

  if (!file || file.type !== "blob") {
    skippedNonBlobs++;
    continue;
  }

  totalBlobs++;

  const filePath = file.path || "";
  const fileSize = file.size || 0;

  // -------------------------------
  // FILE SIZE STATS
  // -------------------------------
  minFileSize = Math.min(minFileSize, fileSize);
  maxFileSize = Math.max(maxFileSize, fileSize);
  totalFileSize += fileSize;

  // -------------------------------
  // DEPTH ANALYSIS
  // -------------------------------
  const parts = filePath.split("/").filter(Boolean);
  maxDepth = Math.max(maxDepth, parts.length);

  // -------------------------------
  // EXTENSION DETECTION
  // More robust regex (avoids folder dot confusion)
  // -------------------------------
  const match = filePath.match(/\.([^.\/]+)$/);

  if (match) {
    const ext = match[1].toLowerCase();
    extensions.add(ext);

    extensionFrequency[ext] = (extensionFrequency[ext] || 0) + 1;
  } else {
    filesWithoutExtension++;
    unmatchedPaths.push(filePath);
  }

  // -------------------------------
  // FOLDER DETECTION
  // -------------------------------
  if (parts.length > 1) {
    const topFolder = parts[0];
    folders.add(topFolder);

    folderFileCount[topFolder] =
      (folderFileCount[topFolder] || 0) + 1;
  } else {
    rootLevelFiles++;
  }

  // -------------------------------
  // FILE NAME CAPTURE
  // -------------------------------
  const name = parts[parts.length - 1] || "";
  fileNames.add(name);
}

// ===============================
// FINAL STAT CALCULATIONS
// ===============================
const avgFileSize =
  totalBlobs > 0
    ? Math.round(totalFileSize / totalBlobs)
    : 0;

if (minFileSize === Number.MAX_SAFE_INTEGER) {
  minFileSize = 0;
}

// ===============================
// RETURN STRUCTURED OUTPUT
// ===============================
return [{
  json: {

    // ----------------------------------
    // STRUCTURAL DATA (LLM INPUT)
    // ----------------------------------
    extensions: Array.from(extensions),
    folders: Array.from(folders),
    sampleFileNames: Array.from(fileNames).slice(0, 200),

    extensionFrequency,
    folderFileCount,

    // ----------------------------------
    // DIAGNOSTIC + VALIDATION DATA
    // ----------------------------------
    traversalStats: {
      totalTreeItems,
      totalBlobsProcessed: totalBlobs,
      skippedNonBlobItems: skippedNonBlobs,
      filesWithoutExtension,
      rootLevelFiles,
      uniqueExtensionCount: extensions.size,
      uniqueFolderCount: folders.size,
      uniqueFileNameCount: fileNames.size,
      minFileSize,
      maxFileSize,
      avgFileSize,
      maxFolderDepth: maxDepth
    },

    // Only return first 50 unmatched to avoid payload explosion
    unmatchedPaths: unmatchedPaths.slice(0, 50),
    // ----------------------------------
    // INCLUDE FULL REPO TREE
    // ----------------------------------
    //fullRepoTree: tree
  }
}];

