// ==========================================
// 1️⃣ Extract raw LLM text safely
// ==========================================
const rawText =
  $json.output?.[0]?.content?.[0]?.text || "";

if (!rawText) {
  throw new Error("Empty LLM response.");
}

// ==========================================
// 2️⃣ Remove Markdown + Comments
// ==========================================
let cleaned = rawText
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim()
  // Remove block comments /* ... */
  .replace(/\/\*[\s\S]*?\*\//g, "")
  // Remove line comments //
  .replace(/\/\/.*$/gm, "");

// ==========================================
// 3️⃣ Extract JSON block safely
// ==========================================
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
  throw new Error("No valid JSON object found in LLM output.");
}

let parsed;

try {
  parsed = JSON.parse(jsonMatch[0]);
} catch (err) {
  throw new Error(
    "Failed to parse cleaned LLM JSON: " + err.message
  );
}

// ==========================================
// 4️⃣ Normalize + Clean Arrays
// ==========================================
function normalizeArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  if (typeof value === "string") return [value];
  return [];
}

// Remove invalid / noisy entries
function cleanArray(arr) {
  return [
    ...new Set(
      arr
        .map(v => String(v).trim())
        .filter(v =>
          v &&
          !v.toLowerCase().includes("lint and formatting") &&
          !v.includes(":") // remove accidental explanation strings
        )
    )
  ];
}

const tierAConfigFiles = cleanArray(
  normalizeArray(parsed.tierAConfigFiles)
);

const ignoreFolders = cleanArray(
  normalizeArray(parsed.ignoreFolders)
);

const ignorePatterns = cleanArray(
  normalizeArray(parsed.ignorePatterns)
);

const codeExtensions = cleanArray(
  normalizeArray(parsed.codeExtensions)
);

// ==========================================
// 5️⃣ Final Output (Stable Structure)
// ==========================================
return [
  {
    json: {
      tierAConfigFiles,
      ignoreFolders,
      ignorePatterns,
      codeExtensions,

      counts: {
        tierAConfigFiles: tierAConfigFiles.length,
        ignoreFolders: ignoreFolders.length,
        ignorePatterns: ignorePatterns.length,
        codeExtensions: codeExtensions.length
      }
    }
  }
];
